#include <stdio.h>



int main(void) {
    int first = 1;
    for (int n = 100; n <= 200; n++) {
        int prime = 1;
        for (int d = 2; d <= n / d; d++) if (n % d == 0) { prime = 0; break; }
        if (prime) { printf("%s%d", first ? "" : " ", n); first = 0; }
    }
    putchar('\n');
    return 0;
}
